import os, glob, json, re

def load_grids():
    """Load all demo pairs from the session file for this task"""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}

    try:
        t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    except:
        return {}

    # Find all demo pairs and test input
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]

    return G

G = load_grids()
print("Loaded grids:")
for k, v in G.items():
    print(f"  {k}: shape {len(v)}x{len(v[0]) if v else 'empty'}")
    print(f"    Input: {v[0] if len(v) >= 2 else 'N/A'}")

